829:memory_sub_partition::breakdown_request_to_sector_requests(mem_fetch *mf) {
830:  std::vector<mem_fetch *> result;
831:  mem_access_sector_mask_t sector_mask = mf->get_access_sector_mask();
832:  if (mf->get_data_size() == SECTOR_SIZE &&
833:      mf->get_access_sector_mask().count() == 1) {
834:    result.push_back(mf);
835:  } else if (mf->get_data_size() == MAX_MEMORY_ACCESS_SIZE) {
836:    // break down every sector
837:    mem_access_byte_mask_t mask;
838:    for (unsigned i = 0; i < SECTOR_CHUNCK_SIZE; i++) {
839:      for (unsigned k = i * SECTOR_SIZE; k < (i + 1) * SECTOR_SIZE; k++) {
840:        mask.set(k);
841:      }
842:      mem_fetch *n_mf = m_mf_allocator->alloc(
843:          mf->get_addr() + SECTOR_SIZE * i, mf->get_access_type(),
844:          mf->get_access_warp_mask(), mf->get_access_byte_mask() & mask,
845:          std::bitset<SECTOR_CHUNCK_SIZE>().set(i), SECTOR_SIZE, mf->is_write(),
846:          m_gpu->gpu_tot_sim_cycle + m_gpu->gpu_sim_cycle, mf->get_wid(),
847:          mf->get_sid(), mf->get_tpc(), mf, mf->get_streamID());
848:
849:      result.push_back(n_mf);
850:    }
851:    // This is for constant cache
852:  } else if (mf->get_data_size() == 64 &&
853:             (mf->get_access_sector_mask().all() ||
