1149:      unsigned warpId = inst.warp_id();
1150:      unsigned tid = m_warp_size * warpId + t;
1151:
1152:      // virtual function
1153:      checkExecutionStatusAndUpdate(inst, t, tid);
1154:    }
1155:  }
1156:  // here, we generate memory acessess and set the status if thread (done?)
1157:  if (inst.is_load() || inst.is_store()) {
1158:    inst.generate_mem_accesses();
1159:  }
1160:}
