258:void memory_stats_t::memlatstat_read_done(mem_fetch *mf) {
259:  if (m_memory_config->SST_mode) {
260:    // in SST mode, we just calculate mem latency
261:    unsigned mf_latency;
262:    mf_latency =
263:        (m_gpu->gpu_sim_cycle + m_gpu->gpu_tot_sim_cycle) - mf->get_timestamp();
264:    num_mfs++;
265:    mf_total_lat += mf_latency;
266:    if (mf_latency > max_mf_latency) max_mf_latency = mf_latency;
267:  } else if (m_memory_config->gpgpu_memlatency_stat) {
268:    unsigned mf_latency = memlatstat_done(mf);
269:    if (mf_latency >
270:        mf_max_lat_table[mf->get_tlx_addr().chip][mf->get_tlx_addr().bk])
271:      mf_max_lat_table[mf->get_tlx_addr().chip][mf->get_tlx_addr().bk] =
272:          mf_latency;
273:    unsigned icnt2sh_latency;
274:    icnt2sh_latency = (m_gpu->gpu_tot_sim_cycle + m_gpu->gpu_sim_cycle) -
275:                      mf->get_return_timestamp();
276:    tot_icnt2sh_latency += icnt2sh_latency;
277:    icnt2sh_lat_table[LOGB2(icnt2sh_latency)]++;
278:    if (icnt2sh_latency > max_icnt2sh_latency)
279:      max_icnt2sh_latency = icnt2sh_latency;
280:  }
